/// `AggregateScan` — kernel/repository.rs's own trait, given a real
/// per-aggregate body here: one `if` per aggregate this domain declared,
/// the same "Domain::Aggregate" prefix `instances()`'s own dump arms
/// already use, each returning that one aggregate's own (id, to_json())
/// listing straight off its repository's `entries()`. Falls through to
/// the trait's own default (`None`) for any prefix that matches none of
/// them — kernel/cli.rs turns that into a clean "unknown aggregate"
/// refusal, never a panic. `scan_each` is the same listing borrowed, so a declared query clones
/// only the rows it keeps; both read the repositories' cached `to_json()` renderings.
impl crate::kernel::AggregateScan for Store {
    fn scan(&self, aggregate: &str) -> Option<Vec<(String, crate::kernel::Json)>> {
        if aggregate == "Echo::Beacon" {
            return Some(
                self.beacon
                    .json_entries(|record| record.to_json())
                    .map(|(id, json)| (id.clone(), json.clone()))
                    .collect(),
            );
        }
        if aggregate == "Echo::Lamp" {
            return Some(
                self.lamp
                    .json_entries(|record| record.to_json())
                    .map(|(id, json)| (id.clone(), json.clone()))
                    .collect(),
            );
        }
        if aggregate == "Echo::Fuse" {
            return Some(
                self.fuse
                    .json_entries(|record| record.to_json())
                    .map(|(id, json)| (id.clone(), json.clone()))
                    .collect(),
            );
        }
        None
    }

    fn scan_each(
        &self,
        aggregate: &str,
        visit: &mut dyn FnMut(&str, &crate::kernel::Json),
    ) -> bool {
        if aggregate == "Echo::Beacon" {
            for (id, json) in self.beacon.json_entries(|record| record.to_json()) {
                visit(id, json);
            }
            return true;
        }
        if aggregate == "Echo::Lamp" {
            for (id, json) in self.lamp.json_entries(|record| record.to_json()) {
                visit(id, json);
            }
            return true;
        }
        if aggregate == "Echo::Fuse" {
            for (id, json) in self.fuse.json_entries(|record| record.to_json()) {
                visit(id, json);
            }
            return true;
        }
        false
    }
}

